package com.rustyledger;

import java.math.BigDecimal;

public class Transaction {
    public final String verb;
    public final String date;
    public final String fromId;
    public final String toId;
    public final BigDecimal amount;
    public final String fromCur;
    public final BigDecimal fee;
    public final BigDecimal credited;
    public boolean reversed;

    public Transaction(String verb, String date, String fromId, String toId,
                       BigDecimal amount, String fromCur, BigDecimal fee,
                       BigDecimal credited) {
        this.verb = verb;
        this.date = date;
        this.fromId = fromId;
        this.toId = toId;
        this.amount = amount;
        this.fromCur = fromCur;
        this.fee = fee;
        this.credited = credited;
        this.reversed = false;
    }
}

package com.rustyledger;

import java.math.BigDecimal;
import java.util.*;

public class LedgerState {
    public final Map<String, Account> accounts = new HashMap<>();
    public final Map<String, BigDecimal> used = new HashMap<>();
    public final Map<String, Transaction> txs = new LinkedHashMap<>();
    public final List<String> audit = new ArrayList<>();
    public final Map<String, int[]> counts = new HashMap<>();
    public final Map<String, Map<String, BigDecimal>> fees = new HashMap<>();
    public int auditSeq = 0;
    public int txSeq = 0;

    public String reject(String verb, String date, String code, String message) {
        if (date != null) {
            int[] c = counts.computeIfAbsent(date, k -> new int[2]);
            c[1]++;
        }
        String auditDate = (date == null) ? "????-??-??" : date;
        auditSeq++;
        audit.add(String.format("%03d  %s %s REJECTED %s", auditSeq, verb, auditDate, code));
        return "REJECTED " + code + ": " + message;
    }

    public String accept(String verb, String date, String txId, String extra) {
        int[] c = counts.computeIfAbsent(date, k -> new int[2]);
        c[0]++;
        auditSeq++;
        audit.add(String.format("%03d  %s %s OK %s", auditSeq, verb, date, txId));
        return "OK " + txId + " " + extra;
    }

    public void addFee(String date, String currency, BigDecimal delta) {
        if (delta.signum() == 0) return;
        Map<String, BigDecimal> m = fees.computeIfAbsent(date, k -> new TreeMap<>());
        m.put(currency, m.getOrDefault(currency, BigDecimal.ZERO).add(delta));
    }
}

package com.rustyledger;

import java.math.BigDecimal;
import java.math.RoundingMode;

public class CurrencyService {
    private BigDecimal rate(String currency) {
        if (currency.equals("EUR")) return new BigDecimal("4.30");
        if (currency.equals("USD")) return new BigDecimal("4.00");
        return new BigDecimal("1.00");
    }

    public BigDecimal convert(BigDecimal amount, String from, String to, String tier) {
        BigDecimal inPln = amount.multiply(rate(from)).setScale(4, RoundingMode.HALF_UP);
        BigDecimal result = inPln.divide(rate(to), 4, RoundingMode.HALF_UP);
        if (!"STAFF".equals(tier)) {
            result = result.multiply(new BigDecimal("0.985"));
        }
        return result.setScale(2, RoundingMode.HALF_DOWN);
    }
}

package com.rustyledger;

import java.math.BigDecimal;
import java.math.RoundingMode;

public class FeeService {
    public BigDecimal calculateTransferFee(String tier, BigDecimal amount) {
        if ("STANDARD".equals(tier)) {
            return amount.multiply(new BigDecimal("0.005")).setScale(2, RoundingMode.HALF_UP)
                    .max(new BigDecimal("0.20"));
        } else if ("PREMIUM".equals(tier)) {
            return amount.multiply(new BigDecimal("0.0025")).setScale(2, RoundingMode.HALF_UP)
                    .max(new BigDecimal("0.10")).min(new BigDecimal("5.00"));
        }
        return new BigDecimal("0.00");
    }

    public BigDecimal calculateWithdrawalFee(String tier) {
        return "STANDARD".equals(tier) ? new BigDecimal("1.00") : BigDecimal.ZERO;
    }
}

package com.rustyledger;

import java.math.BigDecimal;

public class LimitService {
    public String checkLimitAndFunds(LedgerState state, String date, Account a, 
                                     BigDecimal amount, BigDecimal fee) {
        BigDecimal limit;
        BigDecimal overdraft = BigDecimal.ZERO;
        if ("STANDARD".equals(a.tier)) {
            limit = new BigDecimal("5000.00");
        } else if ("PREMIUM".equals(a.tier)) {
            limit = new BigDecimal("20000.00");
            overdraft = new BigDecimal("500.00");
        } else {
            limit = new BigDecimal("50000.00");
        }

        BigDecimal usedToday = state.used.getOrDefault(a.id + "|" + date, BigDecimal.ZERO);
        if (usedToday.add(amount).compareTo(limit) > 0) {
            return "LIMIT_EXCEEDED: daily limit " + limit + " for " + a.tier;
        }

        BigDecimal needed = amount.add(fee);
        if (a.balance.subtract(needed).compareTo(overdraft.negate()) < 0) {
            return "INSUFFICIENT_FUNDS: balance " + a.balance + " " + a.currency + 
                   ", needed " + needed + " " + a.currency;
        }
        return null;
    }
}

package com.rustyledger;

import java.math.BigDecimal;

public class BankingEngine {
    private final LedgerState state;
    private final CurrencyService currencyService = new CurrencyService();
    private final FeeService feeService = new FeeService();
    private final LimitService limitService = new LimitService();

    public BankingEngine(LedgerState state) { this.state = state; }

    public String submit(String line) throws BankingException {
        if (line == null || line.trim().isEmpty()) {
            throw new BankingException("???", null, "BAD_INSTRUCTION", "empty instruction");
        }
        String[] f = line.split("\\|", -1);
        String verb = f[0];
        int want = getWant(verb);
        if (want == -1) throw new BankingException("???", null, "BAD_INSTRUCTION", "unknown verb " + verb);
        if (f.length != want) throw new BankingException(verb, null, "BAD_INSTRUCTION", verb + " needs " + want + " fields");

        String date = f[1];
        if (!date.matches("\\d{4}-\\d{2}-\\d{2}")) throw new BankingException(verb, null, "BAD_DATE", date);

        if (verb.equals("REVERSE")) return handleReverse(date, f[2]);

        String amountText = verb.equals("TRANSFER") ? f[4] : f[3];
        if (!amountText.matches("\\d+(\\.\\d{1,2})?")) throw new BankingException(verb, date, "BAD_AMOUNT", amountText);
        BigDecimal amount = new BigDecimal(amountText).setScale(2, java.math.RoundingMode.HALF_UP);
        if (amount.signum() <= 0) throw new BankingException(verb, date, "BAD_AMOUNT", amountText);

        if (verb.equals("TRANSFER")) return handleTransfer(date, f[2], f[3], amount, f[5]);
        if (verb.equals("WITHDRAW")) return handleWithdraw(date, f[2], amount);
        return handleDeposit(date, f[2], amount);
    }

    private int getWant(String v) {
        return switch (v) { case "TRANSFER" -> 6; case "WITHDRAW", "DEPOSIT" -> 4; case "REVERSE" -> 3; default -> -1; };
    }

    private String handleTransfer(String date, String fromId, String toId, BigDecimal amount, String currency) throws BankingException {
        Account from = state.accounts.get(fromId);
        Account to = state.accounts.get(toId);
        if (from == null) throw new BankingException("TRANSFER", date, "UNKNOWN_ACCOUNT", fromId);
        if (to == null) throw new BankingException("TRANSFER", date, "UNKNOWN_ACCOUNT", toId);
        if (fromId.equals(toId)) throw new BankingException("TRANSFER", date, "SAME_ACCOUNT", "cannot transfer to the same account");
        if (!from.currency.equals(currency)) throw new BankingException("TRANSFER", date, "CURRENCY_MISMATCH", fromId + " holds " + from.currency);

        BigDecimal fee = feeService.calculateTransferFee(from.tier, amount);
        String err = limitService.checkLimitAndFunds(state, date, from, amount, fee);
        if (err != null) {
            String[] parts = err.split(": ", 2);
            throw new BankingException("TRANSFER", date, parts[0], parts[1]);
        }

        BigDecimal credited = from.currency.equals(to.currency) ? amount : currencyService.convert(amount, from.currency, to.currency, from.tier);
        from.balance = from.balance.subtract(amount.add(fee));
        to.balance = to.balance.add(credited);
        state.used.put(fromId + "|" + date, state.used.getOrDefault(fromId + "|" + date, BigDecimal.ZERO).add(amount));

        state.txSeq++;
        String txId = String.format("TX-%06d", state.txSeq);
        state.txs.put(txId, new Transaction("TRANSFER", date, fromId, toId, amount, from.currency, fee, credited));
        state.addFee(date, from.currency, fee);
        return state.accept("TRANSFER", date, txId, "fee=" + fee + " " + from.currency);
    }

    private String handleWithdraw(String date, String id, BigDecimal amount) throws BankingException {
        Account a = state.accounts.get(id);
        if (a == null) throw new BankingException("WITHDRAW", date, "UNKNOWN_ACCOUNT", id);
        BigDecimal fee = feeService.calculateWithdrawalFee(a.tier);
        String err = limitService.checkLimitAndFunds(state, date, a, amount, fee);
        if (err != null) {
            String[] parts = err.split(": ", 2);
            throw new BankingException("WITHDRAW", date, parts[0], parts[1]);
        }
        a.balance = a.balance.subtract(amount.add(fee));
        state.used.put(id + "|" + date, state.used.getOrDefault(id + "|" + date, BigDecimal.ZERO).add(amount));
        state.txSeq++;
        String txId = String.format("TX-%06d", state.txSeq);
        state.txs.put(txId, new Transaction("WITHDRAW", date, id, "", amount, a.currency, fee, amount));
        state.addFee(date, a.currency, fee);
        return state.accept("WITHDRAW", date, txId, "fee=" + fee + " " + a.currency);
    }

    private String handleDeposit(String date, String id, BigDecimal amount) throws BankingException {
        Account a = state.accounts.get(id);
        if (a == null) throw new BankingException("DEPOSIT", date, "UNKNOWN_ACCOUNT", id);
        a.balance = a.balance.add(amount);
        state.txSeq++;
        String txId = String.format("TX-%06d", state.txSeq);
        state.txs.put(txId, new Transaction("DEPOSIT", date, id, "", amount, a.currency, BigDecimal.ZERO, amount));
        return state.accept("DEPOSIT", date, txId, "fee=0.00 " + a.currency);
    }

    private String handleReverse(String date, String txId) throws BankingException {
        Transaction tx = state.txs.get(txId);
        if (tx == null) throw new BankingException("REVERSE", date, "UNKNOWN_TX", txId);
        if (!tx.verb.equals("TRANSFER")) throw new BankingException("REVERSE", date, "NOT_REVERSIBLE", txId + " is a " + tx.verb);
        if (tx.reversed) throw new BankingException("REVERSE", date, "ALREADY_REVERSED", txId);
        if (!tx.date.equals(date)) throw new BankingException("REVERSE", date, "REVERSAL_WINDOW", txId + " was made on " + tx.date);

        Account from = state.accounts.get(tx.fromId);
        Account to = state.accounts.get(tx.toId);
        to.balance = to.balance.subtract(tx.credited);
        BigDecimal back = tx.amount;
        if (from.tier.equals("PREMIUM")) {
            back = back.add(tx.fee);
            if (tx.fee.signum() != 0) state.addFee(date, from.currency, tx.fee.negate());
        }
        from.balance = from.balance.add(back);
        tx.reversed = true;
        state.txSeq++;
        String newId = String.format("TX-%06d", state.txSeq);
        state.txs.put(newId, new Transaction("REVERSE", date, tx.fromId, tx.toId, tx.amount, tx.fromCur, BigDecimal.ZERO, tx.credited));
        return state.accept("REVERSE", date, newId, "reversed " + txId);
    }
}

package com.rustyledger;

import java.math.BigDecimal;
import java.util.*;

public class LedgerImpl implements Ledger {
    private final LedgerState state = new LedgerState();
    private final BankingEngine engine = new BankingEngine(state);

    public void openAccount(String id, String tier, String currency, String openingBalance) {
        if (id == null || id.isBlank() || id.contains("|")) throw new IllegalArgumentException("INVALID ACCOUNT ID");
        if (!Set.of("STANDARD", "PREMIUM", "STAFF").contains(tier)) throw new IllegalArgumentException("INVALID TIER: " + tier);
        if (!Set.of("PLN", "EUR", "USD").contains(currency)) throw new IllegalArgumentException("INVALID CURRENCY: " + currency);
        if (openingBalance == null || !openingBalance.matches("\\d+(\\.\\d{1,2})?")) throw new IllegalArgumentException("INVALID AMOUNT: " + openingBalance);
        if (state.accounts.containsKey(id)) throw new IllegalStateException("ACCOUNT EXISTS: " + id);
        state.accounts.put(id, new Account(id, tier, currency, new BigDecimal(openingBalance).setScale(2)));
    }

    public String balance(String id) {
        Account a = state.accounts.get(id);
        if (a == null) throw new IllegalArgumentException("UNKNOWN ACCOUNT: " + id);
        return a.balance + " " + a.currency;
    }

    public String submit(String line) {
        try { return engine.submit(line); } catch (BankingException e) { return state.reject(e.verb, e.date, e.code, e.message); }
    }

    public List<String> auditLog() { return new ArrayList<>(state.audit); }

    public String dailyReport(String date) {
        int[] c = state.counts.get(date);
        int ok = c == null ? 0 : c[0], rejected = c == null ? 0 : c[1];
        Map<String, BigDecimal> f = state.fees.get(date);
        StringBuilder sb = new StringBuilder();
        if (f != null && !f.isEmpty()) {
            f.forEach((cur, val) -> { if (sb.length() > 0) sb.append(", "); sb.append(val).append(" ").append(cur); });
        }
        String feeText = sb.length() == 0 ? "none" : sb.toString();
        return "REPORT " + date + "\nok: " + ok + "\nrejected: " + rejected + "\nfees: " + feeText;
    }
}

package com.rustyledger;

public class BankingException extends RuntimeException {
    public final String verb;
    public final String date;
    public final String code;
    public final String message;
    public BankingException(String verb, String date, String code, String message) {
        this.verb = verb; this.date = date; this.code = code; this.message = message;
    }
}

